package webhooks

import (
	"sync"
	"time"
)

// Limiter is an in-memory fixed-window rate limiter keyed by
// (party, service). It is deliberately NOT durable: rate limiting is
// protection, not billing, and the gateway is single-node (ADR-002) —
// a restart resets windows, which is documented and accepted (plan 010
// amendment: no rate_limits table, no Redis).
type Limiter struct {
	mu      sync.Mutex
	windows map[string]*limitWindow
	limit   int
	window  time.Duration
}

// limitWindow counts allowances inside one fixed window.
type limitWindow struct {
	start time.Time
	count int
}

// NewLimiter creates a fixed-window limiter. A non-positive limit disables
// limiting entirely (allow-all, remaining reported as -1).
func NewLimiter(limit int, window time.Duration) *Limiter {
	if window <= 0 {
		window = time.Minute
	}
	return &Limiter{windows: make(map[string]*limitWindow), limit: limit, window: window}
}

// Allow consumes one unit for key at now. ok=false means the quota is
// exhausted; remaining and resetAt drive the X-RateLimit-* response
// headers. Old windows are pruned lazily on each call.
func (l *Limiter) Allow(key string, now time.Time) (ok bool, remaining int, resetAt time.Time) {
	if l.limit <= 0 {
		return true, -1, now.Add(l.window)
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	// Lazy prune: drop windows that can no longer be current.
	if len(l.windows) > 1024 {
		for k, w := range l.windows {
			if now.Sub(w.start) >= l.window {
				delete(l.windows, k)
			}
		}
	}

	w, exists := l.windows[key]
	if !exists || now.Sub(w.start) >= l.window {
		w = &limitWindow{start: now}
		l.windows[key] = w
	}

	if w.count >= l.limit {
		return false, 0, w.start.Add(l.window)
	}
	w.count++
	return true, l.limit - w.count, w.start.Add(l.window)
}

package http

import (
	"context"
	"encoding/json"
	"net/http"
	"strconv"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/webhooks"
	gatewayerrors "github.com/konsulin-care/konsulin-gateway/pkg/errors"
	"github.com/konsulin-care/konsulin-gateway/pkg/middleware"
)

// WebhookService defines the interface the webhook handlers consume.
// Defined consumer-side per repo convention.
type WebhookService interface {
	// Enqueue validates the invocation gates and stores the outbox row.
	Enqueue(ctx context.Context, req webhooks.EnqueueRequest) (*webhooks.EnqueueResult, *gatewayerrors.DomainError)
	// Sync runs the inline forward (no persistence, no auto-fallback).
	Sync(ctx context.Context, req webhooks.EnqueueRequest) (*webhooks.SyncResult, *webhooks.LimitInfo, *gatewayerrors.DomainError)
	// Status returns the enqueuer's view of an outbox row.
	Status(ctx context.Context, webhookID, caller string) (*contracts.WebhookStatus, *gatewayerrors.DomainError)
	// HandleResult accepts an inbound async result (ticket or PartyAuth).
	HandleResult(ctx context.Context, req webhooks.ResultRequest) (*webhooks.ResultResponse, *gatewayerrors.DomainError)
	// DLQ lists failed deliveries (admin console).
	DLQ(ctx context.Context) ([]*contracts.WebhookOutbox, error)
}

// WebhooksHandler handles marketplace-gated invocation endpoints.
type WebhooksHandler struct {
	service WebhookService
	// verifyParty resolves a party JWT to its party id (result-callback
	// PartyAuth path; nil disables the path — ticket-only).
	verifyParty func(ctx context.Context, token string) (string, bool)
}

// NewWebhooksHandler creates a WebhooksHandler. verifyParty may be nil
// (result callbacks then accept only single-use result tickets).
func NewWebhooksHandler(service WebhookService, verifyParty func(ctx context.Context, token string) (string, bool)) *WebhooksHandler {
	return &WebhooksHandler{service: service, verifyParty: verifyParty}
}

// enqueueBody is the POST /v1/webhooks (and /sync) body. payload is the
// opaque invocation payload — the gateway never parses it; priced async
// invocations carry it as caller-supplied JWE ciphertext by contract.
type enqueueBody struct {
	To      string          `json:"to"`
	Service string          `json:"service"`
	Payload json.RawMessage `json:"payload"`
	UserRef string          `json:"user_ref"`
}

// decodeEnqueue reads the body and PartyAuth identity; ok=false after the
// error response was written.
func decodeEnqueue(w http.ResponseWriter, r *http.Request, requireIdemKey bool) (webhooks.EnqueueRequest, bool) {
	if requireIdemKey && r.Header.Get("Idempotency-Key") == "" {
		// The idempotency middleware passes header-less POSTs through;
		// ADR-017 requires the key on creates — the handler enforces it.
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeMissingFields, Message: "Idempotency-Key is required",
			HTTPStatus: http.StatusBadRequest,
		})
		return webhooks.EnqueueRequest{}, false
	}
	caller := middleware.PartyFromContext(r)
	if caller == "" {
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeInvalidToken, Message: "party identity missing from context",
			HTTPStatus: http.StatusUnauthorized,
		})
		return webhooks.EnqueueRequest{}, false
	}
	var body enqueueBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeMissingFields, Message: "invalid request body",
			HTTPStatus: http.StatusBadRequest,
		})
		return webhooks.EnqueueRequest{}, false
	}
	return webhooks.EnqueueRequest{
		FromParty: caller, ToParty: body.To, Service: body.Service,
		Payload: body.Payload, UserRef: body.UserRef,
		IdempotencyKey: r.Header.Get("Idempotency-Key"),
	}, true
}

// setRateLimitHeaders renders the limiter telemetry (plan 010 §4). A
// negative limit means no limiter was consulted.
func setRateLimitHeaders(w http.ResponseWriter, limit, remaining int, resetAt interface{ Unix() int64 }) {
	if limit < 0 {
		return
	}
	w.Header().Set("X-RateLimit-Limit", strconv.Itoa(limit))
	w.Header().Set("X-RateLimit-Remaining", strconv.Itoa(remaining))
	w.Header().Set("X-RateLimit-Reset", strconv.FormatInt(resetAt.Unix(), 10))
}

// Enqueue handles POST /v1/webhooks — async marketplace-gated invocation
// (party-authenticated, Idempotency-Key required). 202 {webhook_id};
// entitlement denials surface 402 GW-HOOK-006 before any payload moves.
func (h *WebhooksHandler) Enqueue(w http.ResponseWriter, r *http.Request) {
	req, ok := decodeEnqueue(w, r, true)
	if !ok {
		return
	}
	res, derr := h.service.Enqueue(r.Context(), req)
	if res != nil {
		setRateLimitHeaders(w, res.Limit, res.Remaining, res.ResetAt)
	}
	if derr != nil {
		writeError(w, r, derr)
		return
	}
	writeJSON(w, http.StatusAccepted, map[string]string{"webhook_id": res.WebhookID})
}

// Sync handles POST /v1/webhooks/sync — inline forward: the upstream
// response relays verbatim; timeouts surface 504 GW-HOOK-005, network
// failures 502 GW-HOOK-003. No outbox row is ever written; the caller
// may re-invoke async after a failure (providers dedupe on webhook-id).
func (h *WebhooksHandler) Sync(w http.ResponseWriter, r *http.Request) {
	req, ok := decodeEnqueue(w, r, true)
	if !ok {
		return
	}
	res, limit, derr := h.service.Sync(r.Context(), req)
	if limit != nil {
		setRateLimitHeaders(w, limit.Limit, limit.Remaining, limit.ResetAt)
	}
	if derr != nil {
		writeError(w, r, derr)
		return
	}
	writeJSON(w, res.StatusCode, map[string]interface{}{
		"status_code":  res.StatusCode,
		"body":         string(res.Body),
		"content_type": res.ContentType,
		"webhook_id":   res.WebhookID,
	})
}

// statusResponse is the GET /v1/webhooks/{id}/status wire shape.
type statusResponse struct {
	State         string `json:"state"`
	Attempts      int    `json:"attempts"`
	NextAttemptAt string `json:"next_attempt_at"`
	LastError     string `json:"last_error,omitempty"`
	CreatedAt     string `json:"created_at"`
}

// Status handles GET /v1/webhooks/{id}/status — enqueuer-only (foreign
// callers get 404, no existence disclosure).
func (h *WebhooksHandler) Status(w http.ResponseWriter, r *http.Request) {
	caller := middleware.PartyFromContext(r)
	if caller == "" {
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeInvalidToken, Message: "party identity missing from context",
			HTTPStatus: http.StatusUnauthorized,
		})
		return
	}
	st, derr := h.service.Status(r.Context(), chi.URLParam(r, "id"), caller)
	if derr != nil {
		writeError(w, r, derr)
		return
	}
	writeJSON(w, http.StatusOK, statusResponse{
		State:         st.State,
		Attempts:      st.Attempts,
		NextAttemptAt: st.NextAttemptAt.UTC().Format(time.RFC3339),
		LastError:     st.LastError,
		CreatedAt:     st.CreatedAt.UTC().Format(time.RFC3339),
	})
}

// resultBody is the POST /v1/webhooks/{id}/result body.
type resultBody struct {
	Result string `json:"result"`
}

// Result handles POST /v1/webhooks/{id}/result — inbound async result
// (GW-HOOK-007). Auth: single-use result ticket (Bearer) or PartyAuth
// where the caller is the invocation's recipient. 202 when accepted; a
// missing buyer callbacks endpoint drops the result with an audit event.
func (h *WebhooksHandler) Result(w http.ResponseWriter, r *http.Request) {
	var body resultBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil || body.Result == "" {
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeMissingFields, Message: "result is required",
			HTTPStatus: http.StatusBadRequest,
		})
		return
	}

	ticket := ""
	caller := ""
	if auth := r.Header.Get("Authorization"); len(auth) > 7 && auth[:7] == "Bearer " {
		bearer := auth[7:]
		// The bearer is EITHER a single-use result ticket (engine path) or
		// a party JWT from the invocation's recipient (PartyAuth path).
		// Dispatch by what verifies; a foreign party token resolves to a
		// caller the service rejects with 404.
		if h.verifyParty != nil {
			if partyID, ok := h.verifyParty(r.Context(), bearer); ok {
				caller = partyID
			}
		}
		if caller == "" {
			ticket = bearer
		}
	}

	res, derr := h.service.HandleResult(r.Context(), webhooks.ResultRequest{
		WebhookID:   chi.URLParam(r, "id"),
		Ticket:      ticket,
		CallerParty: caller,
		Result:      body.Result,
	})
	if derr != nil {
		writeError(w, r, derr)
		return
	}
	writeJSON(w, http.StatusAccepted, res)
}

// dlqResponse is the GET /v1/webhooks/dlq wire shape.
type dlqResponse struct {
	Webhooks []dlqEntry `json:"webhooks"`
}

// dlqEntry is one failed delivery in the admin DLQ listing.
type dlqEntry struct {
	ID        string `json:"id"`
	ToParty   string `json:"to_party"`
	Service   string `json:"service"`
	Attempts  int    `json:"attempts"`
	LastError string `json:"last_error"`
	CreatedAt string `json:"created_at"`
}

// DLQ handles GET /v1/webhooks/dlq — admin session required at the route
// (AdminAuth); returns failed deliveries with error details (plan 010 §3).
func (h *WebhooksHandler) DLQ(w http.ResponseWriter, r *http.Request) {
	rows, err := h.service.DLQ(r.Context())
	if err != nil {
		writeError(w, r, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeInternal, Message: "failed to load DLQ",
			HTTPStatus: http.StatusInternalServerError,
		})
		return
	}
	entries := make([]dlqEntry, 0, len(rows))
	for _, row := range rows {
		entries = append(entries, dlqEntry{
			ID: row.ID, ToParty: row.ToParty, Service: row.Service,
			Attempts: row.Attempts, LastError: row.LastError,
			CreatedAt: row.CreatedAt.UTC().Format(time.RFC3339),
		})
	}
	writeJSON(w, http.StatusOK, dlqResponse{Webhooks: entries})
}

package webhooks

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
	gatewayerrors "github.com/konsulin-care/konsulin-gateway/pkg/errors"
	"github.com/konsulin-care/konsulin-gateway/pkg/ulid"
)

// EnqueueRequest is a party's ask to invoke a provider's listed service.
type EnqueueRequest struct {
	FromParty      string
	ToParty        string
	Service        string
	Payload        json.RawMessage
	UserRef        string
	IdempotencyKey string
}

// EnqueueResult carries the webhook id plus rate-limit telemetry for the
// X-RateLimit-* headers (present whenever the limiter was consulted).
type EnqueueResult struct {
	WebhookID string
	Limit     int
	Remaining int
	ResetAt   time.Time
}

// Enqueue validates the invocation gates (recipient, listing, tier, rate
// limit, entitlement), then stores the outbox row: priced listings persist
// the payload (caller-supplied JWE by contract), zero-price listings never
// persist it (memory-held, at-most-once). Idempotent on the
// Idempotency-Key: replays return the original webhook id.
func (s *Service) Enqueue(ctx context.Context, req EnqueueRequest) (*EnqueueResult, *gatewayerrors.DomainError) {
	if strings.TrimSpace(req.ToParty) == "" || strings.TrimSpace(req.Service) == "" || len(req.Payload) == 0 {
		return nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeMissingFields, Message: "to, service, and payload are required",
			HTTPStatus: 400,
		}
	}

	listing, limit, derr := s.resolveInvocation(ctx, req.FromParty, req.ToParty, req.Service, req.UserRef)
	res := &EnqueueResult{}
	if limit != nil {
		res.Limit, res.Remaining, res.ResetAt = limit.Limit, limit.Remaining, limit.ResetAt
	}
	if derr != nil {
		return res, derr
	}

	// Idempotent replay: an already-stored key returns the original id.
	if req.IdempotencyKey != "" {
		if existing, err := s.outbox.GetByIdempotencyKey(ctx, req.IdempotencyKey); err == nil && existing != nil {
			res.WebhookID = existing.ID
			return res, nil
		}
	}

	now := time.Now().UTC()
	id := ulid.New()
	criticality := contracts.WebhookCriticalityPriced
	var body []byte
	if listing.Price == 0 {
		// Free tier: metadata-only row; payload lives in memory for the
		// retry window and is never written to disk.
		criticality = contracts.WebhookCriticalityFree
		s.memBodies.Store(id, []byte(req.Payload))
	} else {
		body = []byte(req.Payload)
	}

	row := &contracts.WebhookOutbox{
		ID: id, FromParty: req.FromParty, ToParty: req.ToParty,
		Service: req.Service, ListingID: listing.ListingID, EndpointURL: listing.EndpointURL,
		HeaderJSON: map[string]interface{}{
			"type": contracts.WebhookKindInvocation, "X-Webhook-Service": req.Service,
		},
		Body: body, State: contracts.WebhookStatePending,
		NextAttemptAt: now, CreatedAt: now,
		IdempotencyKey: req.IdempotencyKey, Criticality: criticality,
	}
	if req.UserRef != "" {
		row.HeaderJSON["user_ref"] = req.UserRef
	}

	if err := s.outbox.Insert(ctx, row); err != nil {
		var conflict contracts.ErrIdempotencyConflict
		if errors.As(err, &conflict) {
			existing, gerr := s.outbox.GetByIdempotencyKey(ctx, req.IdempotencyKey)
			if gerr == nil && existing != nil {
				s.ForgetBody(id)
				res.WebhookID = existing.ID
				return res, nil
			}
		}
		s.ForgetBody(id)
		return res, failClosed("webhook outbox insert failed")
	}

	// Audit follows the money path: priced invocations only.
	if criticality == contracts.WebhookCriticalityPriced {
		_ = s.audit.Log(ctx, AuditActorSystem, AuditEnqueued, id, map[string]interface{}{
			"from": req.FromParty, "to": req.ToParty, "service": req.Service,
			"listing_id": listing.ListingID,
		})
	}
	res.WebhookID = id
	return res, nil
}

// LimitInfo is the limiter outcome rendered as response headers.
type LimitInfo struct {
	Limit     int
	Remaining int
	ResetAt   time.Time
}

// resolveInvocation runs the shared gate chain — recipient active, listing
// resolvable, tier eligible, rate limit, entitlement — and returns the
// resolved listing. Every deny is fail-closed with zero side effects.
func (s *Service) resolveInvocation(ctx context.Context, from, to, service, userRef string) (*contracts.Listing, *LimitInfo, *gatewayerrors.DomainError) {
	provider, err := s.parties.GetByID(ctx, to)
	if err != nil {
		return nil, nil, failClosed("party lookup failed")
	}
	if provider == nil {
		return nil, nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodePartyNotFound, Message: "recipient party not found", HTTPStatus: 404,
		}
	}
	if provider.State != "active" {
		return nil, nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodePartyNotActive, Message: "recipient party not active", HTTPStatus: 403,
		}
	}

	listing, err := s.listings.FindActiveByProviderAndName(ctx, to, service)
	if err != nil {
		return nil, nil, failClosed("listing lookup failed")
	}
	if listing == nil || listing.Invocation != contracts.ListingInvocationWebhook {
		return nil, nil, &gatewayerrors.DomainError{
			Code:       gatewayerrors.CodeWebhookListingMissing,
			Message:    "no active webhook listing for this service",
			HTTPStatus: 404,
		}
	}

	// Tier gate (plan 011 §5b hook): stub passes every active party in v1
	// (two-tier world); the unofficial tier's b2c exclusion activates
	// when that tier becomes settable.
	mode := "b2b"
	if listing.PriceScope == contracts.ListingPriceScopeUser {
		mode = "b2c"
	}
	if !tierEligible(provider.Tier, mode) {
		return nil, nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodePartyNotActive, Message: "provider tier not eligible for this mode", HTTPStatus: 403,
		}
	}

	info := &LimitInfo{Limit: -1, Remaining: -1, ResetAt: time.Now().Add(time.Minute)}
	if s.limiter != nil {
		ok, remaining, resetAt := s.limiter.Allow(from+"\x00"+service, time.Now())
		info = &LimitInfo{Limit: s.limiter.limit, Remaining: remaining, ResetAt: resetAt}
		if !ok {
			return nil, info, &gatewayerrors.DomainError{
				Code: gatewayerrors.CodeRateLimited, Message: "rate limit exceeded", HTTPStatus: 429,
			}
		}
	}

	if ok, derr := s.entitled(ctx, from, listing, userRef); !ok {
		if derr != nil {
			return nil, info, derr
		}
		return nil, info, &gatewayerrors.DomainError{
			Code:       gatewayerrors.CodeWebhookPaymentRequired,
			Message:    "payment required for this service",
			HTTPStatus: 402,
		}
	}
	return listing, info, nil
}

// entitled implements the monetization gate: free party-scoped listings
// open to any active party; user-scoped and priced listings require the
// caller's PAID payment row (gateway-side check, answer to contract
// behavior T6). price_scope=user additionally matches customer_ref.
func (s *Service) entitled(ctx context.Context, from string, listing *contracts.Listing, userRef string) (bool, *gatewayerrors.DomainError) {
	if listing.Price == 0 && listing.PriceScope == contracts.ListingPriceScopeParty {
		return true, nil
	}
	row, err := s.payments.FindEntitlement(ctx, from, listing.ListingID)
	if err != nil {
		return false, failClosed("entitlement lookup failed")
	}
	if row == nil {
		return false, nil
	}
	if listing.PriceScope == contracts.ListingPriceScopeUser {
		if userRef == "" || row.CustomerRef != userRef {
			return false, nil
		}
	}
	return true, nil
}

// tierEligible gates invocation modes by provider tier (plan 011 §5b
// hook). v1 two-tier world: every active party passes; the unofficial
// tier's b2c exclusion activates when that tier becomes settable.
func tierEligible(tier, mode string) bool {
	_, _ = tier, mode
	return true
}

package webhooks

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"time"

	"go.uber.org/zap"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
)

// processRow delivers one row and applies the outcome class. Returns the
// row's terminal/deferred classification for Tick accounting.
func (w *Worker) processRow(ctx context.Context, row *contracts.WebhookOutbox, now time.Time) outcome {
	kind := kindOf(row)

	// Body resolution. Free-tier rows persist no payload: it lives in
	// process memory until delivered; a restart strands it (payload_lost).
	var payload []byte
	if kind == contracts.WebhookKindInvocation {
		if row.Body != nil {
			payload = row.Body
		} else if w.resolveBody != nil {
			if p, ok := w.resolveBody(row.ID); ok {
				payload = p
			}
		}
		if payload == nil {
			w.failRow(ctx, row, row.Attempts, "payload_lost", AuditFailed, now)
			return outcomeFailed
		}
	} else {
		payload = row.Body
		if payload == nil {
			w.failRow(ctx, row, row.Attempts, "payload_lost", AuditFailed, now)
			return outcomeFailed
		}
	}

	// Delivery-side rate limit (plan 010: quota at enqueue AND delivery).
	// Exceeded -> transient: consumes an attempt, backs off.
	if w.limiter != nil {
		if ok, _, _ := w.limiter.Allow(row.ToParty+"\x00"+row.Service, now); !ok {
			return w.retryOrFail(ctx, row, "delivery rate limit exceeded", now)
		}
	}

	if err := validateEndpoint(row.EndpointURL); err != nil {
		w.failRow(ctx, row, row.Attempts+1, err.Error(), AuditFailed, now)
		return outcomeFailed
	}

	attempts := row.Attempts + 1
	token, reqBody, ok := w.buildRequest(row, kind, payload, ctx)
	if !ok {
		return w.retryOrFail(ctx, row, "signing failed", now)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, row.EndpointURL, bytes.NewReader(reqBody))
	if err != nil {
		w.failRow(ctx, row, attempts, "request build failed: "+err.Error(), AuditFailed, now)
		return outcomeFailed
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Webhook-Id", row.ID)
	req.Header.Set("X-Webhook-Service", row.Service)
	req.Header.Set("Content-Type", "application/json")
	if w.signer != nil {
		req.Header.Set("X-Webhook-Kid", w.signer.Kid())
	}

	start := time.Now()
	resp, err := w.client.Do(req)
	latency := time.Since(start)
	if err != nil {
		w.log.Info("webhook delivery attempt failed",
			zap.String("webhook_id", row.ID), zap.String("service", row.Service),
			zap.String("to", row.ToParty), zap.Int("attempts", attempts),
			zap.Duration("latency", latency), zap.Error(err))
		return w.retryOrFail(ctx, row, "network error: "+err.Error(), now)
	}
	defer func() { _ = resp.Body.Close() }()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxUpstreamBody))

	w.log.Info("webhook delivery attempt",
		zap.String("webhook_id", row.ID), zap.String("service", row.Service),
		zap.String("to", row.ToParty), zap.Int("attempts", attempts),
		zap.Int("status", resp.StatusCode), zap.Duration("latency", latency))

	switch {
	case resp.StatusCode >= 200 && resp.StatusCode <= 299:
		if err := w.outbox.MarkDelivered(ctx, row.ID, attempts, time.Now().UTC()); err != nil && !errors.Is(err, sql.ErrNoRows) {
			w.log.Warn("webhook mark delivered failed", zap.String("webhook_id", row.ID), zap.Error(err))
			return outcomeDeferred
		}
		if row.Criticality == contracts.WebhookCriticalityPriced {
			_ = w.audit.Log(ctx, AuditActorSystem, AuditDelivered, row.ID, map[string]interface{}{
				"from": row.FromParty, "to": row.ToParty, "service": row.Service,
				"attempts": attempts, "status": resp.StatusCode,
			})
		}
		w.markSettlementNotified(ctx, row, now)
		if w.forgetBody != nil {
			w.forgetBody(row.ID)
		}
		return outcomeDelivered
	case resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500:
		return w.retryOrFail(ctx, row, fmt.Sprintf("upstream status %d", resp.StatusCode), now)
	default:
		// Terminal 4xx (except 429): no retry (ADR-008).
		w.failRow(ctx, row, attempts, fmt.Sprintf("upstream status %d", resp.StatusCode), AuditFailed, now)
		return outcomeFailed
	}
}

// markSettlementNotified stamps payments.notified_at after a settlement
// notification is delivered (plan 009 §2). The payment_id travels in the
// outbox row's header snapshot; non-settlement rows and missing repos are
// no-ops. Delivery-time only: enqueued-but-undelivered notifications
// leave the column NULL.
func (w *Worker) markSettlementNotified(ctx context.Context, row *contracts.WebhookOutbox, now time.Time) {
	if w.payments == nil || row.Service != contracts.WebhookServiceSettlement {
		return
	}
	paymentID, _ := row.HeaderJSON["payment_id"].(string)
	if paymentID == "" {
		return
	}
	if err := w.payments.MarkNotified(ctx, paymentID, now); err != nil {
		w.log.Warn("settlement notified_at mark failed", zap.String("webhook_id", row.ID), zap.Error(err))
	}
}

// buildRequest signs the delivery token and shapes the upstream body:
// invocations wrap the payload as {"envelope", "result_ticket"} (async
// rows carry a single-use result ticket; sync rows never reach the
// worker); gateway events send their payload verbatim.
func (w *Worker) buildRequest(row *contracts.WebhookOutbox, kind string, payload []byte, ctx context.Context) (token string, body []byte, ok bool) {
	if kind == contracts.WebhookKindInvocation {
		userRef, _ := row.HeaderJSON["user_ref"].(string)
		t, err := w.signer.DeliveryJWT(row.ToParty, row.FromParty, row.ID, userRef, w.deliveryTTL)
		if err != nil {
			return "", nil, false
		}
		envelope := map[string]string{"envelope": string(payload)}
		if ticket := w.resultTicket(ctx, row); ticket != "" {
			envelope["result_ticket"] = ticket
		}
		b, err := json.Marshal(envelope)
		if err != nil {
			return "", nil, false
		}
		return t, b, true
	}
	t, err := w.signer.EventJWT(row.ToParty, purposeForKind(kind), row.ID, w.deliveryTTL)
	if err != nil {
		return "", nil, false
	}
	return t, payload, true
}

// resultTicket returns a result ticket token for the row, reusing the
// pending jti across attempts (one dedupe key per webhook) and recording
// newly minted jtis in the tickets store. Failures degrade gracefully —
// delivery proceeds without a result channel.
func (w *Worker) resultTicket(ctx context.Context, row *contracts.WebhookOutbox) string {
	if w.tickets == nil || w.signer == nil {
		return ""
	}
	existing, err := w.tickets.GetPendingByScopePurpose(ctx, "webhook-result", row.ID, time.Now().Unix())
	if err == nil && existing != nil && existing.JTI != "" {
		if tok, merr := w.signer.ResultTicketWithJTI(row.ToParty, row.FromParty, row.ID, existing.JTI, w.resultTTL); merr == nil {
			return tok
		}
	}
	token, jti, merr := w.signer.ResultTicket(row.ToParty, row.FromParty, row.ID, w.resultTTL)
	if merr != nil {
		w.log.Warn("webhook result ticket mint failed", zap.String("webhook_id", row.ID), zap.Error(merr))
		return ""
	}
	now := time.Now().Unix()
	_ = w.tickets.Record(ctx, &contracts.Ticket{
		JTI: jti, PartyID: row.ToParty, Aud: row.FromParty,
		Scope: "webhook-result", Purpose: row.ID,
		Iat: now, Exp: now + int64(w.resultTTL.Seconds()),
	})
	return token
}

// retryOrFail applies the retry budget: schedule backoff
// (base * 2^(attempts-1)) or DLQ the row when the budget is exhausted.
func (w *Worker) retryOrFail(ctx context.Context, row *contracts.WebhookOutbox, reason string, now time.Time) outcome {
	attempts := row.Attempts + 1
	if attempts >= w.maxAttempts {
		w.failRow(ctx, row, attempts, reason, AuditDLQ, now)
		return outcomeFailed
	}
	delay := w.backoffBase << row.Attempts // base * 2^attempts (row.Attempts is the prior count)
	next := now.Add(delay)
	if err := w.outbox.ScheduleRetry(ctx, row.ID, attempts, next, reason); err != nil && !errors.Is(err, sql.ErrNoRows) {
		w.log.Warn("webhook schedule retry failed", zap.String("webhook_id", row.ID), zap.Error(err))
		return outcomeDeferred
	}
	w.log.Info("webhook delivery retry scheduled",
		zap.String("webhook_id", row.ID), zap.Int("attempts", attempts),
		zap.Time("next_attempt_at", next), zap.String("reason", reason))
	return outcomeDeferred
}

// failRow transitions the row to failed (terminal 4xx, DLQ, or
// payload_lost), audits priced rows, and drops any in-memory payload.
func (w *Worker) failRow(ctx context.Context, row *contracts.WebhookOutbox, attempts int, reason, auditAction string, now time.Time) {
	if err := w.outbox.MarkFailed(ctx, row.ID, attempts, reason); err != nil && !errors.Is(err, sql.ErrNoRows) {
		w.log.Warn("webhook mark failed failed", zap.String("webhook_id", row.ID), zap.Error(err))
	}
	if row.Criticality == contracts.WebhookCriticalityPriced {
		_ = w.audit.Log(ctx, AuditActorSystem, auditAction, row.ID, map[string]interface{}{
			"from": row.FromParty, "to": row.ToParty, "service": row.Service,
			"attempts": attempts, "reason": reason,
		})
	}
	if w.forgetBody != nil {
		w.forgetBody(row.ID)
	}
	w.log.Info("webhook delivery failed",
		zap.String("webhook_id", row.ID), zap.String("service", row.Service),
		zap.Int("attempts", attempts), zap.String("reason", reason),
		zap.Time("at", now))
}

